using System;

namespace VRCKatamari.Editor.MapGreybox
{
    /// <summary>
    /// Serialisable mirror of Docs/Design/Maps/PicnicLawn/unity_greybox.json.
    /// Field names are the JSON keys verbatim so UnityEngine.JsonUtility can map them;
    /// no properties, no dictionaries, no non-serialisable members.
    /// The JSON is generated by Tools/mapbuild/build_greybox.py and is never edited by hand.
    /// </summary>
    [Serializable]
    public class GreyboxPayload
    {
        public int schema_version;
        public string map_id;
        public string status;
        public string generator;
        public GreyboxBounds bounds;
        public GreyboxScale scale;
        public GreyboxZone[] zones;
        public GreyboxStructure[] structures;
        public GreyboxSpawn[] spawns;
        public GreyboxBankAnchor[] bank_anchors;
        public GreyboxBankRotation bank_rotation;
        public GreyboxSizeGate[] size_gates;
        public GreyboxScatterRegion[] scatter_regions;
        public GreyboxRoute[] routes;
        public GreyboxChokepoint[] chokepoints;
        public GreyboxProp[] props;
    }

    [Serializable]
    public class GreyboxBounds
    {
        public float min_x;
        public float max_x;
        public float min_z;
        public float max_z;
        public float ground_y_m;
    }

    [Serializable]
    public class GreyboxScale
    {
        public string status;
        public float map_extent_x_m;
        public float map_extent_z_m;
        public float ball_start_collision_diameter_m;
        public float ball_max_collision_diameter_m;
        public int ball_band_count;
        public string[] ball_band_ids;
        public string[] ball_band_names_zh;
        public float[] ball_band_min_m;
        public float[] ball_band_max_m;
        public string[] pickup_tier_ids;
        public float[] pickup_diameter_min_m;
        public float[] pickup_diameter_max_m;
        public float max_traversable_slope_percent;
        public float max_route_step_m;
        public float boundary_hedge_height_m;
        public float boundary_hedge_depth_m;
        public float core_hedge_height_m;
        public float core_hedge_depth_m;
        public float core_entrance_clear_m;
        public float core_door_clear_m;
        public float route_width_main_m;
        public float route_width_spur_m;
        public float min_route_margin_over_max_ball_m;
        public float bank_pad_radius_m;
        public int bank_anchor_count;
        public float bank_anchor_period_s;
        public float bank_warning_s;
        public float spawn_to_bank_target_m;
        public string[] camera_band_ids;
        public float[] camera_eye_height_m;
    }

    [Serializable]
    public class GreyboxZone
    {
        public string id;
        public string name_zh;
        public string purpose;
        public string shape_type;
        public float min_x;
        public float max_x;
        public float min_z;
        public float max_z;
        public float ground_y_m;
        public string tier_band_min;
        public string tier_band_max;
        public float area_m2;
        public string surface;
        public string notes;
    }

    [Serializable]
    public class GreyboxStructure
    {
        public int index;
        public string definition_id;
        public string zone_id;
        public string kind;
        public float position_x;
        public float position_y;
        public float position_z;
        public float size_x;
        public float size_y;
        public float size_z;
        public float yaw_deg;
        public string notes;
    }

    [Serializable]
    public class GreyboxSpawn
    {
        public string id;
        public string zone_id;
        public float position_x;
        public float position_y;
        public float position_z;
        public float yaw_deg;
        public string facing;
        public string notes;
    }

    [Serializable]
    public class GreyboxBankAnchor
    {
        public string id;
        public string name_zh;
        public string zone_id;
        public float position_x;
        public float position_y;
        public float position_z;
        public float radius_m;
        public int rotation_order_index;
        public int activate_at_s;
        public string[] entrance_route_ids;
        public string[] approach_route_ids;
        public string notes;
    }

    [Serializable]
    public class GreyboxBankRotation
    {
        public string mode;
        public string[] order;
        public float period_s;
        public float warning_s;
        public float[] activate_at_s;
        public int max_concurrent_bankers;
        public int occupancy_lock;
        public int bank_resets_ball_to_start_size;
    }

    [Serializable]
    public class GreyboxSizeGate
    {
        public string id;
        public string type;
        public string definition_id;
        public float position_x;
        public float position_y;
        public float position_z;
        public float yaw_deg;
        public float clear_width_m;
        public float blocks_ball_diameter_below_m;
        public float absorbable_at_ball_diameter_m;
        public string opens_path;
        public float detour_m;
        public string detour_route;
        public string notes;
    }

    [Serializable]
    public class GreyboxScatterRegion
    {
        public string zone_id;
        public string tier_band;
        public float min_spacing_m;
        public int prop_definition_count;
        public string[] prop_ids;
        public int[] prop_counts_min;
        public int[] prop_counts_max;
        public int count_min_total;
        public int count_max_total;
    }

    [Serializable]
    public class GreyboxRoute
    {
        public string id;
        public string kind;
        public int is_closed;
        public float width_m;
        public float min_clear_width_m;
        public float length_m;
        public int waypoint_count;
        public float[] waypoints_x;
        public float[] waypoints_z;
        public string spawn_id;
        public string bank_anchor_id;
        public string gate_id;
        public string notes;
    }

    [Serializable]
    public class GreyboxChokepoint
    {
        public string id;
        public string type;
        public float position_x;
        public float position_y;
        public float position_z;
        public float clear_width_m;
        public string gate_id;
        public int narrow_small_ball_lane;
        public string notes;
    }

    [Serializable]
    public class GreyboxProp
    {
        public string id;
        public string name_zh;
        public string category;
        public string size_tier;
        public string role;
        public string priority;
        public float real_longest_dim_m;
        public float game_longest_dim_m;
        public int absorb_value;
        public int count;
        public string[] zone_ids;
    }
}
